public class Coloring {

    static int[] natural(int[][] a) {
        int n = a.length;
        int[] order = new int[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        return colour(a, order);
    }

    static int[] largestFirst(int[][] a) {
        int n = a.length;
        Integer[] order = new Integer[n];
        final int[] deg = new int[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
            for (int j = 0; j < n; j++) {
                deg[i] += a[i][j] > 0 ? 1 : 0;
            }
        }
        java.util.Arrays.sort(order, (x, y) -> deg[x] != deg[y] ? Integer.compare(deg[y], deg[x]) : Integer.compare(x, y));
        int[] o = new int[n];
        for (int i = 0; i < n; i++) {
            o[i] = order[i];
        }
        return colour(a, o);
    }

    static int colors(int[] c) {
        int m = 0;
        for (int x : c) {
            m = Math.max(m, x);
        }
        return m;
    }

    private static int[] colour(int[][] a, int[] order) {
        int n = a.length;
        int[] c = new int[n]; // 0 = not coloured yet
        for (int v : order) {
            boolean[] used = new boolean[n + 2];
            for (int w = 0; w < n; w++) {
                if (a[v][w] > 0 && c[w] > 0) {
                    used[c[w]] = true;
                }
            }
            int k = 1;
            while (used[k]) {
                k++;
            }
            c[v] = k;
        }
        return c;
    }
}

